'use client';

// Vendored from MerchFlow Charts components/ui/index.tsx (commit in lib/merch-flow-report/VENDORED.md).
// Generated by scripts/sync-merch-flow-report.mjs; edit the PATCHES there, not this file.

import { useState, type ReactNode, type AnchorHTMLAttributes, type ButtonHTMLAttributes, type InputHTMLAttributes } from 'react';

/**
 * Shared UI primitives.
 *
 * Red is a brand accent — the logo, a thin rule and the chart encodings.
 * White on #E8003D is 4.67:1 (passes AA), but controls stay ink (18.7:1 on
 * white) so red stays rare. Controls are 44px tall and
 * inputs use 16px text so iOS does not zoom on focus.
 */

const BASE =
  'inline-flex h-11 items-center justify-center gap-2 whitespace-nowrap rounded-[10px] px-[18px] text-[15px] font-semibold transition-colors disabled:cursor-not-allowed disabled:opacity-40';

const VARIANTS = {
  primary: 'bg-[#111214] text-white hover:bg-[#2A2C30]',
  secondary: 'bg-[#F1F2F4] text-[#111214] border border-[#E5E7EB] hover:bg-[#E7E9EC]',
  ghost: 'bg-transparent text-[#111214] hover:bg-[#F1F2F4]',
  danger: 'bg-[#FDECEE] text-[#B00020] hover:bg-[#FBDDE1]',
} as const;

export function Button({
  variant = 'primary',
  size = 'md',
  block,
  className = '',
  ...props
}: ButtonHTMLAttributes<HTMLButtonElement> & {
  variant?: keyof typeof VARIANTS;
  size?: 'md' | 'sm';
  block?: boolean;
}) {
  return (
    <button
      type="button"
      {...props}
      className={`${BASE} ${VARIANTS[variant]} ${size === 'sm' ? '!h-9 !px-3 !text-[14px]' : ''} ${block ? 'w-full' : ''} ${className}`}
    />
  );
}

export function LinkButton({
  variant = 'primary',
  size = 'md',
  className = '',
  ...props
}: AnchorHTMLAttributes<HTMLAnchorElement> & {
  variant?: keyof typeof VARIANTS;
  size?: 'md' | 'sm';
}) {
  return (
    <a
      {...props}
      className={`${BASE} ${VARIANTS[variant]} ${size === 'sm' ? '!h-9 !px-3 !text-[14px]' : ''} no-underline ${className}`}
    />
  );
}

export const inputClass =
  'h-11 w-full rounded-[10px] border border-[#E5E7EB] bg-white px-3 text-[16px] text-[#1D1C1D] outline-none placeholder:text-[#9CA3AF] focus:border-[#111214]';

export function Input(props: InputHTMLAttributes<HTMLInputElement>) {
  return <input {...props} className={`${inputClass} ${props.className ?? ''}`} />;
}

/** Password field with a show/hide toggle, so a typo is recoverable. */
export function PasswordInput({
  className = '',
  ...props
}: InputHTMLAttributes<HTMLInputElement>) {
  const [visible, setVisible] = useState(false);
  return (
    <div className="relative">
      <input
        {...props}
        type={visible ? 'text' : 'password'}
        className={`${inputClass} pr-20 ${className}`}
      />
      <button
        type="button"
        onClick={() => setVisible((v) => !v)}
        className="absolute right-1 top-1 h-9 rounded-[8px] px-3 text-[13px] font-semibold text-[#4B5563] hover:bg-[#F1F2F4]"
      >
        {visible ? 'Hide' : 'Show'}
      </button>
    </div>
  );
}

export function Field({
  label,
  hint,
  error,
  children,
}: {
  label: string;
  hint?: ReactNode;
  error?: string;
  children: ReactNode;
}) {
  return (
    <label className="block">
      <span className="block text-[14px] font-semibold text-[#111214]">{label}</span>
      <div className="mt-1.5">{children}</div>
      {error ? (
        <span className="mt-1.5 block text-[13px] text-[#B00020]">{error}</span>
      ) : hint ? (
        <span className="mt-1.5 block text-[13px] text-[#6B7280]">{hint}</span>
      ) : null}
    </label>
  );
}

export function Card({ className = '', children }: { className?: string; children: ReactNode }) {
  return (
    <div
      className={`rounded-[14px] border border-[#E5E7EB] bg-white shadow-[0_1px_2px_rgba(17,18,20,0.06)] ${className}`}
    >
      {children}
    </div>
  );
}

const TONES = {
  neutral: 'bg-[#F1F2F4] text-[#4B5563]',
  success: 'bg-[#E7F6EE] text-[#05603A]',
  warn: 'bg-[#FFF4E0] text-[#8A4B00]',
  danger: 'bg-[#FDECEE] text-[#B00020]',
} as const;

export function Badge({
  tone = 'neutral',
  children,
}: {
  tone?: keyof typeof TONES;
  children: ReactNode;
}) {
  return (
    <span
      className={`inline-flex items-center gap-1 rounded-full px-2.5 py-1 text-[12px] font-semibold ${TONES[tone]}`}
    >
      {children}
    </span>
  );
}

export function Chip({
  active,
  children,
  ...props
}: ButtonHTMLAttributes<HTMLButtonElement> & { active?: boolean }) {
  return (
    <button
      type="button"
      {...props}
      className={`h-9 rounded-full border px-3.5 text-[14px] font-semibold transition-colors ${
        active
          ? 'border-[#111214] bg-[#111214] text-white'
          : 'border-[#E5E7EB] bg-white text-[#4B5563] hover:bg-[#F1F2F4]'
      }`}
    >
      {children}
    </button>
  );
}

export function EmptyState({
  title,
  body,
  action,
}: {
  title: string;
  body: string;
  action?: ReactNode;
}) {
  return (
    <div className="rounded-[14px] border border-dashed border-[#D1D5DB] bg-white px-6 py-14 text-center">
      <h3 className="text-[16px] font-semibold text-[#111214]">{title}</h3>
      <p className="mx-auto mt-1.5 max-w-sm text-[14px] text-[#6B7280]">{body}</p>
      {action && <div className="mt-5 flex justify-center">{action}</div>}
    </div>
  );
}

/** Copy-to-clipboard with inline confirmation, so nothing needs a toast. */
export function CopyButton({
  value,
  label = 'Copy',
  size = 'sm',
  variant = 'secondary',
}: {
  value: string;
  label?: string;
  size?: 'md' | 'sm';
  variant?: keyof typeof VARIANTS;
}) {
  const [copied, setCopied] = useState(false);

  return (
    <Button
      variant={variant}
      size={size}
      onClick={async () => {
        try {
          await navigator.clipboard.writeText(value);
          setCopied(true);
          setTimeout(() => setCopied(false), 1800);
        } catch {
          setCopied(false);
        }
      }}
    >
      {copied ? 'Copied' : label}
    </Button>
  );
}

/**
 * Side panel on desktop, bottom sheet on phone — one component, because the
 * content is identical and only the edge it anchors to changes.
 */
export function Drawer({
  open,
  onClose,
  label,
  children,
}: {
  open: boolean;
  onClose: () => void;
  label: string;
  children: ReactNode;
}) {
  if (!open) return null;

  return (
    <div
      className="fixed inset-0 z-50 flex items-end justify-center sm:items-stretch sm:justify-end"
      role="dialog"
      aria-modal="true"
      aria-label={label}
    >
      <button aria-label="Close" onClick={onClose} className="absolute inset-0 bg-black/45" />
      <div className="relative flex max-h-[88vh] w-full flex-col overflow-y-auto rounded-t-[14px] bg-white sm:max-h-none sm:w-[420px] sm:rounded-none">
        {children}
      </div>
    </div>
  );
}

export function Modal({
  open,
  onClose,
  label,
  children,
}: {
  open: boolean;
  onClose: () => void;
  label: string;
  children: ReactNode;
}) {
  if (!open) return null;

  return (
    <div
      className="fixed inset-0 z-50 flex items-end justify-center p-0 sm:items-center sm:p-4"
      role="dialog"
      aria-modal="true"
      aria-label={label}
    >
      <button aria-label="Cancel" onClick={onClose} className="absolute inset-0 bg-black/50" />
      <div className="relative w-full max-w-md rounded-t-[14px] bg-white p-6 sm:rounded-[14px]">
        {children}
      </div>
    </div>
  );
}
